for (int i = 0; i < enemies.Count; i++)
    pos[i] = enemies[i].transform.position;          // main thread, one by one

var h = new SteerJob { pos = pos, vel = vel }.Schedule(enemies.Count, 64);
h.Complete();                                        // the job itself: 0.1 ms

for (int i = 0; i < enemies.Count; i++)
    enemies[i].transform.position = pos[i];          // main thread again

// if the two loops cost 2 ms, Burst sped up the cheap part

// 16 elements: the work is cheaper than scheduling it
// 1) plain C#: often the right answer
for (int i = 0; i < slots.Length; i++) slots[i].Refresh();

// 2) the same Burst job, but Run(): no queue, no threads
new ScoreJob { scores = scores }.Run(scores.Length);

// 3) a Burst static method called directly from the main thread
[BurstCompile]
static class Score
{
    [BurstCompile]
    public static unsafe float Sum(float* data, int count)   // no NativeArray here
    {
        float s = 0f;
        for (int i = 0; i < count; i++) s += data[i];
        return s;
    }
}

// a poor Burst candidate: branches, strings, Unity API, events
void Think(Npc npc)
{
    if (npc.Quest != null && npc.Quest.State == "active")
        ui.ShowHint(npc.Quest.Title);
    var target = FindObjectsByType<Player>(FindObjectsSortMode.None)[0];  // every frame
    if (npc.GetComponent<Health>().Value < 10) npc.Flee(target);
}

// a good one: the numeric core over arrays
[BurstCompile]
struct ThreatJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> npcPos;
    public float3 playerPos;
    [WriteOnly] public NativeArray<float> threat;
    public void Execute(int i) => threat[i] = 1f / (1f + math.distancesq(npcPos[i], playerPos));
}

// a thin managed shell, a Burst core inside
public class CrowdSystem : MonoBehaviour
{
    NativeArray<float3> pos, vel;            // Persistent, owned here only
    JobHandle handle;

    void Update()   { handle = new SteerJob { pos = pos, vel = vel }.Schedule(pos.Length, 64); }
    void LateUpdate() { handle.Complete(); }
    void OnDestroy() { handle.Complete(); pos.Dispose(); vel.Dispose(); }
}

// the core is plain math with no Unity API: easy to test with Burst off,
// where the same code runs as ordinary C#

using Unity.Profiling;

public class CrowdSystem : MonoBehaviour
{
    // created once; the name is what you will see in the Profiler
    static readonly ProfilerMarker s_Steer = new ProfilerMarker("Crowd.Steer");

    void Update()
    {
        using (s_Steer.Auto())      // Begin here, End at the closing brace
        {
            SteerAll();
        }
        MoveAll();
    }
}

void Update()
{
    var enemies = FindObjectsByType<Enemy>(FindObjectsSortMode.None);
    for (int i = 0; i < enemies.Length; i++)
        pos[i] = enemies[i].transform.position;
    new SteerJob { pos = pos, vel = vel }.Run(enemies.Length);
    for (int i = 0; i < enemies.Length; i++)
        enemies[i].transform.position = pos[i];
}

